<?php require "../config/auth.php";require "../config/database.php";if($_SERVER["REQUEST_METHOD"]==="POST"){$vals=[];foreach(["nama", "nim", "semester", "kelas", "email", "whatsapp", "divisi", "foto"] as $c)$vals[]=$_POST[$c]??"";$pdo->prepare("INSERT INTO anggota (nama,nim,semester,kelas,email,whatsapp,divisi,foto) VALUES (?,?,?,?,?,?,?,?)")->execute($vals);header("Location:anggota.php");exit;}if(isset($_GET["delete"])){$pdo->prepare("DELETE FROM anggota WHERE id=?")->execute([(int)$_GET["delete"]]);header("Location:anggota.php");exit;}$rows=$pdo->query("SELECT * FROM anggota ORDER BY id DESC")->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Anggota | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between"><h2>Anggota</h2><a href="index.php">Dashboard</a></div><div class="card p-4 my-4"><form method="post" class="row g-3"><div class="col-md-6"><label class="form-label">Nama</label><input name="nama" class="form-control"></div><div class="col-md-6"><label class="form-label">Nim</label><input name="nim" class="form-control"></div><div class="col-md-6"><label class="form-label">Semester</label><input name="semester" class="form-control"></div><div class="col-md-6"><label class="form-label">Kelas</label><input name="kelas" class="form-control"></div><div class="col-md-6"><label class="form-label">Email</label><input name="email" class="form-control"></div><div class="col-md-6"><label class="form-label">Whatsapp</label><input name="whatsapp" class="form-control"></div><div class="col-md-6"><label class="form-label">Divisi</label><input name="divisi" class="form-control"></div><div class="col-md-6"><label class="form-label">Foto</label><input name="foto" class="form-control"></div><div class="col-12"><button class="btn btn-primary">Tambah</button></div></form></div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>ID</th><th>nama</th><th>nim</th><th>semester</th><th>kelas</th><th>email</th><th>whatsapp</th><th>divisi</th><th>foto</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["nama"])?></td><td><?=e($r["nim"])?></td><td><?=e($r["semester"])?></td><td><?=e($r["kelas"])?></td><td><?=e($r["email"])?></td><td><?=e($r["whatsapp"])?></td><td><?=e($r["divisi"])?></td><td><?=e($r["foto"])?></td><td><a class="btn btn-sm btn-danger" href="?delete=<?=$r["id"]?>" onclick="return confirm('Hapus data?')">Hapus</a></td></tr><?php endforeach;?></tbody></table></div></div></body></html>